import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import * as Busboy from 'busboy'; // import all to access .default
import { Readable } from 'stream';

export const config = {
  api: {
    bodyParser: false,
  },
};

// Helper to convert Web ReadableStream to Node.js Readable stream
function webStreamToNodeStream(webStream) {
  const reader = webStream.getReader();
  return new Readable({
    async read() {
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) {
            this.push(null);
            break;
          }
          this.push(Buffer.from(value));
        }
      } catch (error) {
        this.destroy(error);
      }
    },
  });
}

export async function POST(req) {
  return new Promise((resolve) => {
    // Use busboy default export as constructor
    const BusboyConstructor = Busboy.default;
    const busboy = new BusboyConstructor({
      headers: Object.fromEntries(req.headers),
    });

    let gymId = null;
    let fileBuffers = [];
    let fileMimeType = null;

    busboy.on('field', (fieldname, val) => {
      if (fieldname === 'gym_id') {
        gymId = val;
      }
    });

    busboy.on('file', (fieldname, fileStream, filename, encoding, mimetype) => {
      if (fieldname === 'profilePicture') {
        fileMimeType = mimetype;
        fileStream.on('data', (data) => {
          fileBuffers.push(data);
        });
        fileStream.on('error', (err) => {
          resolve(
            new Response(
              JSON.stringify({ error: 'File stream error: ' + err.message }),
              { status: 500 }
            )
          );
        });
      } else {
        fileStream.resume();
      }
    });

    busboy.on('error', (err) => {
      resolve(
        new Response(
          JSON.stringify({ error: 'Form parsing error: ' + err.message }),
          { status: 500 }
        )
      );
    });

    busboy.on('finish', async () => {
      if (!gymId) {
        return resolve(
          new Response(JSON.stringify({ error: 'gym_id is required' }), { status: 400 })
        );
      }
      if (fileBuffers.length === 0) {
        return resolve(
          new Response(JSON.stringify({ error: 'profilePicture file is required' }), {
            status: 400,
          })
        );
      }

      const fileData = Buffer.concat(fileBuffers);

      const s3 = new S3Client({
        region: 'auto',
        endpoint: process.env.R2_ENDPOINT,
        credentials: {
          accessKeyId: process.env.R2_ACCESS_KEY_ID,
          secretAccessKey: process.env.R2_SECRET_ACCESS_KEY,
        },
      });

      try {
        await s3.send(
          new PutObjectCommand({
            Bucket: process.env.R2_BUCKET,
            Key: gymId,
            Body: fileData,
            ContentType: fileMimeType || 'application/octet-stream',
          })
        );

        resolve(new Response(JSON.stringify({ success: true, key: gymId }), { status: 200 }));
      } catch (uploadError) {
        resolve(
          new Response(
            JSON.stringify({ error: 'Upload failed: ' + uploadError.message }),
            { status: 500 }
          )
        );
      }
    });

    // Convert Web ReadableStream to Node.js Readable and pipe to busboy
    const nodeStream = webStreamToNodeStream(req.body);
    nodeStream.pipe(busboy);
  });
}
